/*
 * Probes contains Kubernetes-compatible probe signals for a component.
 * Each probe maps directly to a K8s probe type, providing binary actionable signals
 * that orchestrators use to make lifecycle decisions.
 * The three signals are orthogonal:
 *   - A component can be started but not ready (loading caches, waiting for dependencies)
 *   - A component can be live but not ready (graceful shutdown, backpressure)
 *   - A component cannot be live without being started (startup is a prerequisite for liveness)
 * Mapping to K8s probe endpoints:
 *   /startupz  -> startup.ok
 *   /healthz   -> liveness.ok
 *   /readyz    -> readiness.ok
 * Mapping to K8s orchestrator actions:
 *   startup.ok == false   -> keep waiting, do not check liveness or readiness
 *   liveness.ok == false  -> restart the container/process
 *   readiness.ok == false -> remove from service endpoints (stop routing traffic)
 * For hierarchical components, parent probe status is typically derived from children:
 *   parent.startup   = ALL children started (AND)
 *   parent.liveness  = ALL children live (AND)
 *   parent.readiness = ALL children ready (AND, or quorum-based depending on component type)
 */
struct  Kentik__Monitoring__V1__Probes
{
  ProtobufCMessage base;
  /*
   * Has this component completed its initialization sequence?
   * Maps to Kubernetes startup probe.
   * While startup.ok is false, liveness and readiness probes should not be evaluated
   * (following K8s semantics where startup probe must pass before other probes activate).
   * This is typically a one-shot signal: once true, it stays true for the
   * lifetime of the component. It resets only on restart.
   */
  Kentik__Monitoring__V1__Probe *startup;
  /*
   * Is this component fundamentally alive and not deadlocked?
   * Maps to Kubernetes liveness probe.
   * When liveness.ok is false, the component should be restarted.
   * This should only fail for unrecoverable internal errors such as:
   *   - Deadlocks
   *   - Corrupted internal state
   *   - Stuck event loops
   * Important: transient dependency failures (database down, upstream timeout)
   * should cause readiness failure, NOT liveness failure. Restarting won't
   * fix an external dependency being down.
   */
  Kentik__Monitoring__V1__Probe *liveness;
  /*
   * Can this component serve traffic and fulfill its purpose right now?
   * Maps to Kubernetes readiness probe.
   * When readiness.ok is false, traffic should not be routed to this component.
   * This signal can toggle dynamically based on:
   *   - Dependency health (database connection lost)
   *   - Backpressure (queue full, rate limiting)
   *   - Graceful shutdown (draining connections)
   *   - Warmup (caches not yet populated after startup)
   * Unlike liveness, readiness failure does NOT trigger a restart.
   * The component remains running and is expected to recover.
   */
  Kentik__Monitoring__V1__Probe *readiness;
};
